#!/usr/bin/env python3
"""Verify the three navigation pages: glossary, architecture diagram, index.

Checks
------
G1  docs/glossary.md exists and every `### Term` block carries a Provenance line
G2  every dotted symbol in a Provenance line is importable
G3  every `path` / `path:line` in a Provenance line exists and is in range
G4  the cited line actually mentions the symbol it is attached to
A1  docs/guides/architecture-diagram.md exists
A2  every `src/agenthicc/...` path named in it exists
A3  every mermaid node id is declared in the Nodes table
A4  no diagram node points outside src/agenthicc/
T1  docs/reference/troubleshooting-index.md exists
T2  every `path#anchor` link resolves to a real heading slug in the target
T3  the coverage table matches the counts measured from the tree
L1  every relative markdown link in all three pages resolves
"""

from __future__ import annotations

import importlib
import pathlib
import re
import sys
import unicodedata

ROOT = pathlib.Path(__file__).resolve().parent
if not (ROOT / "src" / "agenthicc").exists():
    ROOT = pathlib.Path("/root/python_projects/agenthicc")
sys.path.insert(0, str(ROOT / "src"))

problems: list[str] = []
notes: list[str] = []


def problem(page: str, msg: str) -> None:
    problems.append(f"{page}: {msg}")


# --------------------------------------------------------------------------
# slugify, matching python-markdown's toc extension (what MkDocs uses)
# --------------------------------------------------------------------------
def slugify(value: str, separator: str = "-") -> str:
    value = unicodedata.normalize("NFKD", value)
    value = value.encode("ascii", "ignore").decode("ascii")
    value = re.sub(r"[^\w\s-]", "", value.lower())
    return re.sub(rf"[{separator}\s]+", separator, value).strip(separator)


def heading_slugs(path: pathlib.Path) -> set[str]:
    """Slugs MkDocs would generate, with duplicate suffixes (-1, -2 ...)."""
    counts: dict[str, int] = {}
    out: set[str] = set()
    for line in path.read_text(encoding="utf-8").splitlines():
        m = re.match(r"^(#{1,6})\s+(.*?)\s*$", line)
        if not m:
            continue
        base = slugify(m.group(2))
        if base in counts:
            counts[base] += 1
            out.add(f"{base}-{counts[base]}")
        else:
            counts[base] = 0
            out.add(base)
    return out


# --------------------------------------------------------------------------
# G: glossary
# --------------------------------------------------------------------------
GLOSSARY = pathlib.Path("docs/glossary.md")


def check_glossary() -> None:
    if not GLOSSARY.exists():
        problem("glossary", "file is missing")
        return
    text = GLOSSARY.read_text(encoding="utf-8")

    blocks = re.split(r"\n(?=### )", text)
    terms = 0
    prov_lines = 0
    sym_count = path_count = 0

    for block in blocks:
        m = re.match(r"### (.+)", block)
        if not m:
            continue
        term = m.group(1).strip()
        terms += 1
        prov = re.search(r"^\*\*Provenance:\*\*\s*(.+)$", block, re.M)
        if not prov:
            problem("glossary", f"term `{term}` has no **Provenance:** line")
            continue
        prov_lines += 1
        tokens = re.findall(r"`([^`]+)`", prov.group(1))
        if not tokens:
            problem("glossary", f"term `{term}` provenance has no backticked ref")
        path_for_line: dict[str, str] = {}
        for tok in tokens:
            if tok.startswith("src/"):
                continue
            # --- symbol
            sym_count += 1
            obj = _import_symbol(tok)
            if obj is None:
                problem("glossary", f"term `{term}`: cannot import `{tok}`")
                continue
            path_for_line[_short(tok)] = tok
        for tok in re.findall(r"`(src/[^`]+)`", prov.group(1)):
            path_count += 1
            _check_path_ref("glossary", f"term `{term}`", tok, path_for_line)

    notes.append(f"glossary: {terms} terms, {prov_lines} provenance lines")
    notes.append(f"glossary: {sym_count} symbol refs, {path_count} path refs")


def _short(sym: str) -> str:
    return sym.split(".")[-1]


def _import_symbol(dotted: str) -> object | None:
    parts = dotted.split(".")
    for cut in range(len(parts), 0, -1):
        try:
            obj: object = importlib.import_module(".".join(parts[:cut]))
        except Exception:
            continue
        for attr in parts[cut:]:
            try:
                obj = getattr(obj, attr)
            except AttributeError:
                break
        else:
            return obj
        return None
    return None


def _check_path_ref(page: str, where: str, ref: str, syms: dict[str, str]) -> None:
    """Verify `path` or `path:line`, and that the line names the symbol."""
    path_txt, _, line_txt = ref.partition(":")
    p = pathlib.Path(path_txt)
    if not p.exists():
        problem(page, f"{where}: path `{path_txt}` does not exist")
        return
    if not line_txt:
        return
    n = int(line_txt)
    lines = p.read_text(encoding="utf-8").splitlines()
    if not (1 <= n <= len(lines)):
        problem(page, f"{where}: line {n} out of range in `{path_txt}` ({len(lines)} lines)")
        return
    src_line = lines[n - 1]
    # The cited line must mention at least one symbol attached on the same line.
    if syms and not any(re.search(rf"\b{re.escape(s)}\b", src_line) for s in syms):
        problem(
            page,
            f"{where}: `{path_txt}:{n}` is `{src_line.strip()[:60]}` "
            f"which mentions none of {sorted(syms)}",
        )


# --------------------------------------------------------------------------
# A: architecture diagram
# --------------------------------------------------------------------------
DIAGRAM = pathlib.Path("docs/guides/architecture-diagram.md")


def check_diagram() -> None:
    if not DIAGRAM.exists():
        problem("architecture-diagram", "file is missing")
        return
    text = DIAGRAM.read_text(encoding="utf-8")

    # A2: every src/agenthicc path named exists
    paths = sorted(set(re.findall(r"(src/agenthicc/[\w/\.\-]+\.py)", text)))
    for rel in paths:
        if not pathlib.Path(rel).exists():
            problem("architecture-diagram", f"named path `{rel}` does not exist")
    # A4: nothing outside src/agenthicc
    outside = [
        t for t in re.findall(r"`([^`]*\.py)`", text)
        if not t.startswith("src/agenthicc/") and "/" in t and not t.startswith("..")
    ]
    for t in outside:
        problem("architecture-diagram", f"node/ref `{t}` is not under src/agenthicc/")

    # A3: mermaid node ids must be declared in the Nodes table
    mermaid = re.search(r"```mermaid\n(.*?)```", text, re.S)
    if not mermaid:
        problem("architecture-diagram", "no ```mermaid block found")
        return
    ids = set()
    for line in mermaid.group(1).splitlines():
        line = line.strip()
        if not line or line.startswith("graph"):
            continue
        for side in re.split(r"-->", line):
            m = re.match(r"^([A-Za-z_][\w]*)", side.strip())
            if m:
                ids.add(m.group(1))

    nodes_section = re.search(r"^## Nodes\n(.*?)^## ", text, re.S | re.M)
    if not nodes_section:
        problem("architecture-diagram", "no `## Nodes` table found")
        return
    declared = set(re.findall(r"^\|\s*`([A-Za-z_]\w*)`\s*\|", nodes_section.group(1), re.M))
    undeclared = sorted(ids - declared)
    if undeclared:
        problem("architecture-diagram", f"mermaid ids not in Nodes table: {undeclared}")
    unused = sorted(declared - ids)
    if unused:
        problem("architecture-diagram", f"Nodes rows never used in mermaid: {unused}")

    notes.append(
        f"architecture-diagram: {len(paths)} paths, {len(ids)} mermaid nodes, "
        f"{len(declared)} declared"
    )


# --------------------------------------------------------------------------
# T: troubleshooting index
# --------------------------------------------------------------------------
INDEX = pathlib.Path("docs/reference/troubleshooting-index.md")


def check_index() -> None:
    if not INDEX.exists():
        problem("troubleshooting-index", "file is missing")
        return
    text = INDEX.read_text(encoding="utf-8")

    links = re.findall(r"\]\(([^)\s]+#[^)\s]+)\)", text)
    bad = 0
    for link in sorted(set(links)):
        target, _, anchor = link.partition("#")
        p = (INDEX.parent / target).resolve()
        if not p.exists():
            problem("troubleshooting-index", f"link `{link}`: file missing")
            bad += 1
            continue
        if anchor not in heading_slugs(p):
            problem("troubleshooting-index", f"link `{link}`: no such heading anchor")
            bad += 1

    # T3: measured counts
    guide_pages, subsections, bullet_only = _measure_troubleshooting()
    symptom = _measure_symptoms()
    checks = [
        ("Guide pages with a troubleshooting section", guide_pages),
        ("Traps indexed individually", subsections),
        ("Symptom entries indexed from `docs/usage/`", symptom),
    ]
    for label, actual in checks:
        m = re.search(rf"^\|\s*{re.escape(label)}\s*\|\s*(\d+)\s*\|", text, re.M)
        if not m:
            problem("troubleshooting-index", f"coverage table row missing: {label}")
        elif int(m.group(1)) != actual:
            problem(
                "troubleshooting-index",
                f"coverage row `{label}` says {m.group(1)}, measured {actual}",
            )

    notes.append(
        f"troubleshooting-index: {len(set(links))} anchors checked, {bad} bad; "
        f"guides={guide_pages} subsections={subsections} bullet_only={bullet_only}"
    )


def _measure_troubleshooting() -> tuple[int, int, int]:
    guides, subs, bullet_only = 0, 0, 0
    for f in sorted(pathlib.Path("docs/guides").glob("*.md")):
        lines = f.read_text(encoding="utf-8").splitlines()
        idx = [
            i for i, l in enumerate(lines)
            if re.match(r"^##\s+Troubleshooting", l)
        ]
        if not idx:
            continue
        guides += 1
        start = idx[-1]
        n_sub = 0
        for l in lines[start + 1:]:
            if re.match(r"^##\s", l) and not l.startswith("###"):
                break
            if l.startswith("### "):
                n_sub += 1
        if n_sub:
            subs += n_sub
        else:
            bullet_only += 1
    return guides, subs, bullet_only


def _measure_symptoms() -> int:
    f = pathlib.Path("docs/usage/12-troubleshooting.md")
    n = 0
    for l in f.read_text(encoding="utf-8").splitlines():
        if l.startswith("## ") and "related" not in l.lower():
            n += 1
    return n


# --------------------------------------------------------------------------
# L: every relative link in the three pages resolves
# --------------------------------------------------------------------------
def check_relative_links() -> None:
    total = 0
    for page in (GLOSSARY, DIAGRAM, INDEX):
        if not page.exists():
            continue
        for link in re.findall(r"\]\(([^)\s]+)\)", page.read_text(encoding="utf-8")):
            if link.startswith(("http://", "https://", "mailto:", "#")):
                continue
            total += 1
            target, _, anchor = link.partition("#")
            if not target:
                continue
            p = (page.parent / target).resolve()
            if not p.exists():
                problem(str(page), f"link `{link}`: file missing")
            elif anchor and p.suffix == ".md" and anchor not in heading_slugs(p):
                problem(str(page), f"link `{link}`: no such heading anchor")
    notes.append(f"relative links resolved: {total}")


def main() -> int:
    check_glossary()
    check_diagram()
    check_index()
    check_relative_links()
    for n in notes:
        print(f"note  {n}")
    for p in problems:
        print(f"FAIL  {p}")
    print(f"\nnav pages=3 problems={len(problems)}")
    return 1 if problems else 0


if __name__ == "__main__":
    raise SystemExit(main())

