def slugify(value: str, separator: str = "-") -> str:
    """Slug exactly as MkDocs renders it.

    Delegates to python-markdown's toc slugify when available, because that is
    the function MkDocs actually uses.  A hand-rolled equivalent silently
    disagreed on headings beginning with punctuation (for example
    ``### `--headless` without `--workflow` ``), which produced both false
    positives and false negatives in this checker.
    """
    try:
        from markdown.extensions.toc import slugify as md_slugify

        return md_slugify(value, separator)
    except Exception:
        value = unicodedata.normalize("NFKD", value)
        value = value.encode("ascii", "ignore").decode("ascii")
        value = re.sub(r"[^\w\s-]", "", value.lower())
        return re.sub(rf"[{separator}\s]+", separator, value)

