#!/usr/bin/env python3
"""Verify README.md: links, anchors, and every factual claim it makes.

README.md sits OUTSIDE the MkDocs docs directory, so `mkdocs build --strict`
never validates it and no existing gate covers it.  That is the real fragility:
its 45 local links and its surface tables can rot silently.  This checker closes
that gap.

Criteria
--------
L1  every relative link target exists
L2  every `path#anchor` resolves to a real MkDocs heading slug
C1  every `agenthicc <cmd ...>` invocation in a code block resolves against the
    live parser tree (subcommands and flags)
C2  every workflow named in a backticked table row exists in the registry
C3  every count claim about workflows/modes/slash-commands matches reality
C4  every mode named exists in BUILTIN_MODES
C5  every `/slash` command used exists (BUILTIN_COMMANDS, bootstrap skills, or
    the background-injected set)
C6  no removed module is asserted to exist (agenthicc.api, TranscriptModel,
    render_frame_ansi) unless the surrounding text marks it historical
S1  the landing-page sections the goal requires are present
"""

from __future__ import annotations

import pathlib
import re
import sys

ROOT = pathlib.Path(__file__).resolve().parent
if not (ROOT / "src" / "agenthicc").exists():
    ROOT = pathlib.Path("/root/python_projects/agenthicc")
sys.path.insert(0, str(ROOT / "src"))

README = ROOT / "README.md"

problems: list[str] = []
notes: list[str] = []


def problem(msg: str) -> None:
    problems.append(msg)


# --------------------------------------------------------------------------
# slugify — exactly what MkDocs uses
# --------------------------------------------------------------------------
def slugify(value: str, separator: str = "-") -> str:
    try:
        from markdown.extensions.toc import slugify as md_slugify

        return md_slugify(value, separator)
    except Exception:
        import unicodedata

        v = unicodedata.normalize("NFKD", value).encode("ascii", "ignore").decode()
        v = re.sub(r"[^\w\s-]", "", v.lower())
        return re.sub(rf"[{separator}\s]+", separator, v)


def headings(path: pathlib.Path) -> set[str]:
    out: set[str] = set()
    for line in path.read_text(encoding="utf-8").splitlines():
        m = re.match(r"^#{1,6}\s+(.*)$", line.strip())
        if m:
            out.add(slugify(m.group(1).strip(), "-"))
    return out


def readme_text() -> str:
    return README.read_text(encoding="utf-8")


def prose_only(text: str) -> str:
    """README with fenced code replaced by blank lines (line numbers kept)."""
    out, in_fence = [], False
    for line in text.splitlines():
        if line.lstrip().startswith("```"):
            in_fence = not in_fence
            out.append("")
        else:
            out.append("" if in_fence else line)
    return "\n".join(out)


# --------------------------------------------------------------------------
# L1 / L2 — links and anchors
# --------------------------------------------------------------------------
def check_links() -> None:
    text = prose_only(readme_text())
    n = 0
    for lineno, line in enumerate(text.splitlines(), 1):
        for m in re.finditer(r"\[[^\]]*\]\(([^)\s]+)\)", line):
            target = m.group(1)
            if target.startswith(("http://", "https://", "mailto:")):
                continue
            n += 1
            file_part, _, frag = target.partition("#")
            p = (ROOT / file_part).resolve() if file_part else README.resolve()
            if not p.exists():
                problem(f"L1 line {lineno}: link target `{target}` missing")
                continue
            if frag and p.suffix == ".md" and frag not in headings(p):
                problem(
                    f"L2 line {lineno}: anchor `#{frag}` not found in "
                    f"{p.relative_to(ROOT)}"
                )
    notes.append(f"L1/L2: {n} local links, all targets and anchors checked")


# --------------------------------------------------------------------------
# CLI surface, from the live registry (single source of truth)
# --------------------------------------------------------------------------
def cli_surface() -> tuple[set[str], dict[str, set[str]]]:
    """Return (command paths, flag->paths map) from the real parser."""
    from agenthicc.cli.registry import _as_tree, _discover, _wire  # noqa: PLC0415

    _discover(strict_cli_shadow=False, config=None)
    tree = _as_tree()

    paths: set[str] = set()

    def walk(node: dict, prefix: tuple[str, ...]) -> None:
        children = node.get("children") or {}
        if not children and prefix:
            paths.add(" ".join(prefix))
            return
        for name, child in children.items():
            walk(child, prefix + (name,))

    if isinstance(tree, dict) and "children" in tree:
        walk(tree, ())
    else:
        for name, node in tree.items():
            walk(node, (name,))

    flags: dict[str, set[str]] = {}
    try:
        from agenthicc.cli.registry import _as_tree as _t  # noqa: F401
    except Exception:
        pass
    return paths, flags


def parser_flags() -> set[str]:
    """All long flags the CLI actually accepts."""
    import argparse  # noqa: PLC0415

    from agenthicc.cli.parser import parse_cli  # noqa: PLC0415

    found: set[str] = set()

