    def walk(node: dict, prefix: tuple[str, ...]) -> None:
        children = node.get("children") or {}
        if not children:
            if prefix:
                paths.add(" ".join(prefix))
            return
        for name, child in children.items():
            walk(child, prefix + (name,))

