        walk(node, (name,))
    return paths


def parser_flags() -> tuple[set[str], set[str]]:
    """Return (all long flags, the subset that consumes a value).

    Getting the value-taking subset right matters: `agenthicc --set
    execution.provider=openai` must not be read as subcommand
    `execution.provider=openai`.
    """
    import argparse  # noqa: PLC0415

    from agenthicc.cli.parser import _add_global_flags  # noqa: PLC0415

    flags: set[str] = set()
    value_flags: set[str] = set()

    def collect(p: argparse.ArgumentParser) -> None:
        for a in p._actions:  # noqa: SLF001 - introspection is the point
            if isinstance(a, argparse._SubParsersAction):  # noqa: SLF001
                for ch in a.choices.values():
                    if isinstance(ch, argparse.ArgumentParser):
                        collect(ch)
                continue
            takes_value = not isinstance(
                a,
                (argparse._StoreTrueAction, argparse._StoreFalseAction,  # noqa: SLF001
                 argparse._HelpAction, argparse._CountAction,  # noqa: SLF001
                 argparse._VersionAction),  # noqa: SLF001
            )
            for opt in a.option_strings:
                if opt.startswith("--"):
                    flags.add(opt)
                    if takes_value:
                        value_flags.add(opt)
                elif opt.startswith("-") and opt != "-":
                    flags.add(opt)
                    if takes_value:
                        value_flags.add(opt)

    parser = argparse.ArgumentParser(prog="agenthicc", add_help=False)
    _add_global_flags(parser)
    collect(parser)
    return flags, value_flags

