#!/usr/bin/env python3
"""Verify the four contributor surfaces: AGENTS.md, CLAUDE.md, CONTRIBUTING.md, docs/contributing.md.

Criteria
--------
P1  every `nox -s <session>` names a real session in noxfile.py
P2  every `uv run <tool> ...` uses a real tool and its path arguments exist
P3  every `--extra <name>` names a declared optional-dependency extra
P4  no file asserts a resolved drift is still open (mkdocs missing / extras mismatch)
P5  the four files agree on the documentation-surface path list and its gate
L1  every relative link target exists
L2  every `path#anchor` resolves via markdown.extensions.toc.slugify
"""

from __future__ import annotations

import pathlib
import re
import shlex
import sys
import tomllib

ROOT = pathlib.Path("/root/python_projects/agenthicc")
FILES = [
    ROOT / "AGENTS.md",
    ROOT / "CLAUDE.md",
    ROOT / "CONTRIBUTING.md",
    ROOT / "docs" / "contributing.md",
]

problems: list[str] = []
notes: list[str] = []


def slugify(value: str, separator: str = "-") -> str:
    from markdown.extensions.toc import slugify as md_slugify

    return md_slugify(value, separator)


def anchors(path: pathlib.Path) -> set[str]:
    import markdown

    md = markdown.Markdown(
        extensions=["toc", "tables", "fenced_code", "admonition", "attr_list"]
    )
    html = md.convert(path.read_text(encoding="utf-8"))
    return set(re.findall(r'id="([^"]+)"', html))


# --- ground truth -----------------------------------------------------------
nox_src = (ROOT / "noxfile.py").read_text()
SESSIONS = set(re.findall(r'name="([a-z_]+)"', nox_src))

pyproject = tomllib.loads((ROOT / "pyproject.toml").read_text())
EXTRAS = set(pyproject["project"]["optional-dependencies"])
SCRIPTS = set(pyproject["project"]["scripts"])

TOOLS = {"pytest", "ruff", "mypy", "mkdocs", "nox", "python", "agenthicc"}
notes.append(f"nox sessions: {len(SESSIONS)}; extras: {sorted(EXTRAS)}")

DOC_SURFACE = {
    "docs/",
    "README.md",
    "AGENTS.md",
    "CLAUDE.md",
    "CONTRIBUTING.md",
    "skills/",
    "llms.txt",
    "llms-full.txt",
}


def code_blocks(text: str) -> list[str]:
    return re.findall(r"```[a-z]*\n(.*?)```", text, re.S)


def check_commands(path: pathlib.Path, text: str) -> int:
    n = 0
    for block in code_blocks(text):
        for raw in block.splitlines():
            line = re.sub(r"\s+#\s.*$", "", raw.strip())
            if not line or line.startswith("#"):
                continue
            try:
                toks = shlex.split(line)
            except ValueError:
                problems.append(f"P2 {path.name}: unparseable command line: {line!r}")
                continue
            if not toks:
                continue
            base = toks[0]
            if base in {"export", "cd", "git", "printf", "echo", "pip"}:
                continue
            if base == "uv" and len(toks) > 1 and toks[1] == "sync":
                for i, t in enumerate(toks):
                    if t == "--extra" and i + 1 < len(toks):
                        e = toks[i + 1]
                        n += 1
                        if e not in EXTRAS:
                            problems.append(f"P3 {path.name}: undeclared extra --extra {e}")
                continue
            if base == "nox":
                pass
            elif base == "uv" and len(toks) > 1 and toks[1] == "run":
                if len(toks) < 3:
                    continue
                base = toks[2]
                toks = toks[2:]
            else:
                problems.append(f"P2 {path.name}: unrecognised command {line!r}")
                continue

            # nox sessions
            if base == "nox":
                for i, t in enumerate(toks):
                    if t in {"-s", "--session"} and i + 1 < len(toks):
                        sess = toks[i + 1]
                        n += 1
                        if sess not in SESSIONS:
                            problems.append(f"P1 {path.name}: unknown nox session `{sess}`")
                continue

            n += 1
            if base not in TOOLS:
                problems.append(f"P2 {path.name}: unknown tool `{base}`")
                continue

            # path-like arguments must exist
            for t in toks[1:]:
                if t.startswith("-"):
                    continue
