def check_stale(path: pathlib.Path, text: str) -> None:
    low = text.lower()
    # P4: resolved drift must no longer be asserted as open
    if "not declared in the project dependency metadata" in low:
        problems.append(f"P4 {path.name}: claims mkdocs is not in project metadata")
    if "mkdocs is not declared" in low:
        problems.append(f"P4 {path.name}: claims mkdocs is not declared")
    for phrase in (
        "once the documentation dependency is installed",
        "adding it to project metadata is",
        "currently being aligned with project metadata",
        "extras and tools declared by",
        "optional-extra and docs-tool",
    ):
        if phrase in low:
            problems.append(f"P4 {path.name}: still asserts open drift: {phrase!r}")
