                continue
        else:
            p = path
        if frag:
            ap = p if p.is_file() else None
            if ap is None or ap.suffix != ".md":
                problems.append(f"L2 {path.name}: anchor into non-markdown {target}")
            elif frag not in anchors(ap):
                problems.append(f"L2 {path.name}: missing anchor {target}")
    return n


