def cli_surface() -> tuple[set[str], set[str]]:
    """Return (leaf command paths, long flags) from the live CLI registry.

    P2 accepts `agenthicc` as a known tool, but that alone would let a
    fabricated subcommand through.  These come from the real parser tree so
    `agenthicc sessions list` and friends are checked, not assumed.
    """
    import argparse

    from agenthicc.cli.parser import _add_global_flags
    from agenthicc.cli.registry import _as_tree, _discover, _wire

    _discover(strict_cli_shadow=False, config=None)
    tree = _as_tree()
    paths: set[str] = set()

    def walk(node: dict, prefix: tuple[str, ...]) -> None:
        children = node.get("children") or {}
        if not children:
            if prefix:
                paths.add(" ".join(prefix))
            return
        for name, child in children.items():
            walk(child, prefix + (name,))

    for name, node in tree.items():
        walk(node, (name,))

    flags: set[str] = set()

    def collect(p: argparse.ArgumentParser) -> None:
        for a in p._actions:  # noqa: SLF001
            if isinstance(a, argparse._SubParsersAction):  # noqa: SLF001
                for ch in a.choices.values():
                    if isinstance(ch, argparse.ArgumentParser):
                        collect(ch)
                continue
            for opt in a.option_strings:
                if opt.startswith("--"):
                    flags.add(opt)

    parser = argparse.ArgumentParser(prog="agenthicc", add_help=False)
    _add_global_flags(parser)
    collect(parser)
    sub = argparse.ArgumentParser(prog="agenthicc", add_help=False)
    _wire(sub, tree)
    collect(sub)
    return paths, flags


CLI_PATHS, CLI_FLAGS = cli_surface()
CLI_TOPS = {p.split()[0] for p in CLI_PATHS}


