#!/usr/bin/env python3
"""Generate verified llms-full.txt sections for four public modules.

Every signature, field name, constant value and description below is read from
the live objects, so the generated text cannot drift from the checkout.
"""

from __future__ import annotations

import dataclasses
import importlib
import inspect
import sys
from typing import Any

sys.path.insert(0, "/root/python_projects/agenthicc/src")

SPECS: list[tuple[str, str, str]] = [
    ("## Conversation journal", "agenthicc.memory.journal", ""),
    ("## Journaled short-term memory", "agenthicc.memory.journaled", ""),
    ("## Workflow checkpoints", "agenthicc.workflows.checkpoint", ""),
]


def own_doc(obj: Any) -> str:
    doc = getattr(obj, "__doc__", None)
    if not doc:
        return ""
    if inspect.isclass(obj) or inspect.isfunction(obj):
        if obj.__module__ in ("builtins",):
            return ""
    else:
        # constants: only an explicit docstring in the defining module counts
        return ""
    first = doc.strip().split("\n\n")[0]
    return " ".join(first.split())


def unquote(text: str) -> str:
    """Drop the PEP 563 string quoting around annotations."""
    out = []
    in_quote: str | None = None
    for ch in text:
        if in_quote:
            if ch == in_quote:
                in_quote = None
            continue
        if ch in "'\"":
            in_quote = ch
            continue
        out.append(ch)
    return "".join(out)


def render_symbol(name: str, obj: Any) -> list[str]:
    lines: list[str] = [f"### {name}", "", "```python"]
    if inspect.isclass(obj):
        if dataclasses.is_dataclass(obj):
            lines.append("@dataclass")
        bases = [
            b.__name__
            for b in getattr(obj, "__bases__", ())
            if b.__name__ not in ("object",)
        ]
        head = f"class {name}({', '.join(bases)})" if bases else f"class {name}"
        lines.append(head)
    elif inspect.isfunction(obj):
        try:
            sig = unquote(str(inspect.signature(obj)))
        except (TypeError, ValueError):
            sig = "(...)"
        ret = unquote(str(inspect.signature(obj).return_annotation))
        if ret != "Signature.empty" and "empty" not in ret:
            lines.append(f"def {name}{sig}")
        else:
            lines.append(f"def {name}{sig}")
    else:
        lines.append(f"{name} = {obj!r}")
    lines.extend(["```", ""])

    if inspect.isclass(obj) and dataclasses.is_dataclass(obj):
        fields = [f.name for f in dataclasses.fields(obj)]
        if len(fields) > 10:
            shown = ", ".join(f"`{f}`" for f in fields[:8])
            lines.append(f"Fields: {shown}, … ({len(fields)} fields total).")
        else:
            lines.append("Fields: " + ", ".join(f"`{f}`" for f in fields) + ".")
        lines.append("")

    doc = own_doc(obj)
    if doc:
        lines.append(doc)
        lines.append("")
    return lines


def render_section(title: str, module: str) -> str:
    mod = importlib.import_module(module)
    doc = " ".join((inspect.getdoc(mod) or "").split("\n\n")[0].split())
    out = [f"{title} — `{module}`", ""]
    if doc:
        out.extend([doc, ""])
    for name in getattr(mod, "__all__", []):
        out.extend(render_symbol(name, getattr(mod, name)))
    # collapse any trailing blank lines, keep one separator
    text = "\n".join(out).rstrip() + "\n"
    return text


def main() -> int:
    parts = [render_section(t, m) for t, m, _ in SPECS]
    sys.stdout.write("\n".join(parts))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

