def fmt_annotation(annot: Any) -> str:
    """Render an annotation, peeling the PEP 563 string quoting."""
    while isinstance(annot, str) and len(annot) >= 2 and annot[0] == annot[-1] and annot[0] in "'\"":
        annot = annot[1:-1]
    if isinstance(annot, str):
        return annot
    return inspect.formatannotation(annot)


def fmt_signature(func: Any) -> str:
    """Build a signature string with unquoted annotations."""
    try:
        sig = inspect.signature(func)
    except (TypeError, ValueError):
        return "(...)"
    parts: list[str] = []
    seen_kw_marker = False
    for p in sig.parameters.values():
        annot = "" if p.annotation is inspect.Parameter.empty else f": {fmt_annotation(p.annotation)}"
        default = "" if p.default is inspect.Parameter.empty else f" = {p.default!r}"
        if p.kind is inspect.Parameter.VAR_POSITIONAL:
            parts.append(f"*{p.name}{annot}")
            seen_kw_marker = True
        elif p.kind is inspect.Parameter.VAR_KEYWORD:
            parts.append(f"**{p.name}{annot}")
        elif p.kind is inspect.Parameter.KEYWORD_ONLY:
            if not seen_kw_marker:
                parts.append("*")
                seen_kw_marker = True
            parts.append(f"{p.name}{annot}{default}")
        elif p.kind is inspect.Parameter.POSITIONAL_ONLY:
            parts.append(f"{p.name}{annot}{default}")
            if not seen_kw_marker and p is sig.parameters[list(sig.parameters)[-1]]:
                parts.append("/")
        else:
            parts.append(f"{p.name}{annot}{default}")
    # trailing "/" when the final parameter is positional-only
    params = list(sig.parameters.values())
    if params and all(p.kind is inspect.Parameter.POSITIONAL_ONLY for p in params):
        if "/" not in parts:
            parts.append("/")
    ret = (
        ""
        if sig.return_annotation is inspect.Signature.empty
        else f" -> {fmt_annotation(sig.return_annotation)}"
    )
    return f"({', '.join(parts)}){ret}"

