def check_module_index(brief: str, full: str) -> None:
    """K6/K7: llms.txt's `## Module index` claim about llms-full.txt.

    The section states that every module it lists imports cleanly and is
    documented, so both halves of that sentence are enforced here: the row must
    import, and the module must appear in an `##`/`###` heading of
    llms-full.txt. A placeholder purpose is not documentation.
    """
    lines = brief.splitlines()
    start = None
    for i, line in enumerate(lines):
        if line.strip().startswith("## ") and "module index" in line.lower():
            start = i + 1
            break
    if start is None:
        problem("K6: no `## Module index` section in llms.txt")
        return

    headings = re.findall(r"^#{2,3}\s+(.*)$", full, re.MULTILINE)
    rows = checked = 0
    for line in lines[start:]:
        if line.startswith("## "):
            break
        if not line.startswith("|"):
            continue
        cells = [c.strip() for c in line.strip().strip("|").split("|")]
        if len(cells) < 2 or set(cells[0]) <= set("-: ") or not cells[0].startswith("`"):
            continue
        rows += 1
        mod = cells[0].strip("`")
        purpose = cells[1]
        try:
            importlib.import_module(mod)
            checked += 1
        except Exception as exc:  # noqa: BLE001
            problem(f"K6: module index row `{mod}` does not import ({exc.__class__.__name__})")
        if not any(f"`{mod}" in h for h in headings):
            problem(f"K6: module index row `{mod}` is not documented in any llms-full.txt heading")
        if purpose.strip(" -—–") == "":
            problem(f"K7: module index row `{mod}` has a placeholder purpose ({purpose!r})")
    notes.append(f"K6/K7: {rows} module index rows, {checked} importable, purposes checked")


