#!/usr/bin/env python3
"""Independent verification of goal #4. Deliberately NOT built on check_llms.py.

Design differences from /tmp/check_llms.py:
  * the section's module is tracked by the most recent heading of level <= 3 that
    contains a backticked *dotted* module, rather than by the `## ` title only
  * a symbol that fails in its stated module is then searched across every
    importable agenthicc module; if found elsewhere it is reported as
    UNSECTIONED (the exact defect class this goal fixed) rather than merely
    unresolved
  * the heading baseline is recomputed from `git show HEAD:llms-full.txt`
    instead of trusting a hardcoded constant
  * `nox -s llms_check` is executed by the verifier itself

Exit 0 only when every check passes.
"""

from __future__ import annotations

import importlib
import pathlib
import re
import subprocess
import sys

ROOT = pathlib.Path("/root/python_projects/agenthicc")
sys.path.insert(0, str(ROOT / "src"))

failures: list[str] = []
notes: list[str] = []


def fail(msg: str) -> None:
    failures.append(msg)


# --- discovery of every importable module in the package -------------------
def all_modules() -> dict[str, object]:
    import agenthicc

    root = pathlib.Path(agenthicc.__file__).parent
    mods: dict[str, object] = {}
    for path in sorted(root.rglob("*.py")):
        rel = path.relative_to(root)
        if any(part == "__pycache__" for part in rel.parts):
            continue
        parts = list(rel.parts)
        if parts[-1] == "__init__.py":
            parts = parts[:-1]
        else:
            parts[-1] = parts[-1][:-3]
        if not parts:
            continue
        name = "agenthicc." + ".".join(parts)
        try:
            mods[name] = importlib.import_module(name)
        except Exception:  # noqa: BLE001
            continue
    return mods


MODS = all_modules()
notes.append(f"V0: {len(MODS)} importable agenthicc modules discovered by walking the tree")


# --- V1: the enforced nox contract ----------------------------------------
def check_nox() -> None:
    r = subprocess.run(
        ["nox", "-s", "llms_check"], cwd=ROOT, capture_output=True, text=True, timeout=900
    )
    out = r.stdout + r.stderr
    notes.append(f"V1: `nox -s llms_check` exit={r.returncode}")
    if r.returncode != 0:
        fail(f"V1: night nox session failed\n{out[-800:]}")
    elif "llms_check OK" not in out:
        fail("V1: nox exited 0 but the OK banner is absent")


# --- V2: heading baseline from git ----------------------------------------
def check_baseline(full: str) -> None:
    head = subprocess.run(
        ["git", "show", "HEAD:llms-full.txt"], cwd=ROOT, capture_output=True, text=True, check=True
    ).stdout
    base = len(re.findall(r"^### ", head, re.M))
    now = len(re.findall(r"^### ", full, re.M))
    notes.append(f"V2: `### ` at HEAD={base}, worktree={now}")
    if base != 206:
        fail(f"V2: recorded baseline drifted — HEAD has {base}, not 206")
    if now < base:
        fail(f"V2: heading count decreased {base} -> {now}")


# --- V3: symbol headings resolve from their stated module -----------------
DOTTED = re.compile(r"`([A-Za-z_]\w*(?:\.[A-Za-z_]\w*)+)`")
SYM = re.compile(r"^[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)?$")


def symbol_shape(raw: str) -> list[str] | None:
    t = raw.strip()
    t = re.split(r"\s+[—–]\s+", t)[0]
    t = t.replace("`", "").strip()
    if not t:
        return None
    toks = [p.strip() for p in re.split(r"\s*/\s*|\s*,\s*|\s+and\s+", t) if p.strip()]
    if not toks or any(not SYM.match(p) for p in toks):
        return None
    return toks


def locate(name: str) -> list[str]:
    """Modules that expose `name` (with Class.attr support)."""
    hits = []
    for modname, mod in MODS.items():
        if "." in name:
            cls_name, attr = name.split(".", 1)
            cls = getattr(mod, cls_name, None)
            if cls is not None and hasattr(cls, attr):
                hits.append(modname)
        elif hasattr(mod, name):
            hits.append(modname)
    return hits


def check_headings(full: str) -> None:
    current_mod: str | None = None
    checked = unsectioned = prose = exempt = 0
    HISTORICAL = re.compile(r"historical|not in the current checkout|superseded", re.I)
    for line in full.splitlines():
        if line.startswith("## ") or line.startswith("### "):
            m = DOTTED.search(line)
            if m and "." in m.group(1):
                # a heading that itself names a module re-points the scope
                current_mod = m.group(1)
        if not line.startswith("### "):
            continue
        raw = line[4:].strip()
        toks = symbol_shape(raw)
        if toks is None:
            prose += 1
            continue
        if HISTORICAL.search(raw) or HISTORICAL.search(full[:0] or ""):
            exempt += len(toks)
            continue
        if current_mod is None:
            exempt += len(toks)
            continue
        for name in toks:
            checked += 1
            ok = "." in name and (
                (cls := getattr(MODS.get(current_mod), name.split(".")[0], None)) is not None
                and hasattr(cls, name.split(".", 1)[1])
            ) or ("." not in name and hasattr(MODS[current_mod], name))
            if ok:
                continue
            elsewhere = [m for m in locate(name) if m != current_mod]
            if elsewhere:
                unsectioned += 1
                fail(
                    f"V3: `### {name}` is filed under {current_mod} but lives in "
                    f"{', '.join(sorted(elsewhere)[:3])}"
                )
            else:
                fail(f"V3: `### {name}` is not resolvable from {current_mod} nor from any module")
    notes.append(
        f"V3: {checked} symbol headings under a module scope, {unsectioned} unsectioned, "
        f"{prose} prose, {exempt} out of scope"
    )


# --- V4: llms.txt important-symbols + module index ------------------------
def find_section(lines: list[str], needle: str) -> tuple[int, int] | None:
    for i, line in enumerate(lines):
        if line.startswith("## ") and needle in line.lower():
            j = i + 1
            while j < len(lines) and not lines[j].startswith("## "):
                j += 1
            return i + 1, j
    return None


def rows_of(lines: list[str], span: tuple[int, int]) -> list[list[str]]:
    out = []
    for line in lines[span[0] : span[1]]:
        if not line.startswith("|"):
            continue
        cells = [c.strip() for c in line.strip().strip("|").split("|")]
        if len(cells) >= 2 and not set(cells[0]) <= set("-: "):
            out.append(cells)
    return out


def check_brief(brief: str, full: str) -> None:
    lines = brief.splitlines()
    span = find_section(lines, "important symbols")
    if span is None:
        fail("V4: no `## Important symbols` section in llms.txt")
        return
    n = 0
    for cells in rows_of(lines, span):
        syms = re.findall(r"`([A-Za-z_]\w*)`", cells[0])
        mods = re.findall(r"`([A-Za-z_]\w*(?:\.[A-Za-z_]\w*)+)`", cells[1])
        if not syms or not mods:
            continue
        for sym in syms:
            n += 1
            hits = [m for m in mods if sym in locate(sym) and m in locate(sym)]
            if not hits:
                fail(f"V4: llms.txt says `{sym}` comes from {mods} but it does not")
    notes.append(f"V4: {n} important-symbol rows resolved")

    span = find_section(lines, "module index")
    if span is None:
        fail("V5: no `## Module index` section in llms.txt")
        return
    headings = re.findall(r"^#{2,3}\s+(.*)$", full, re.MULTILINE)
    rows = checked = 0
    for cells in rows_of(lines, span):
        if not cells[0].startswith("`"):
            continue
        rows += 1
        mod = cells[0].strip("`")
        if mod not in MODS:
            fail(f"V5: module index row `{mod}` is not importable")
        else:
            checked += 1
        if not any(f"`{mod}" in h for h in headings):
            fail(f"V5: module index row `{mod}` appears in no llms-full.txt heading")
        if cells[1].strip(" -—–") == "":
            fail(f"V5: module index row `{mod}` has a placeholder purpose")
    notes.append(f"V5: {rows} module-index rows, {checked} importable")


def main() -> int:
    full = (ROOT / "llms-full.txt").read_text(encoding="utf-8")
    brief = (ROOT / "llms.txt").read_text(encoding="utf-8")

    check_nox()
    check_baseline(full)
    check_headings(full)
    check_brief(brief, full)

    for n in notes:
        print(f"note  {n}")
    for f in failures[:40]:
        print(f"FAIL  {f}")
    if len(failures) > 40:
        print(f"      … {len(failures) - 40} more")
    print(f"\nindependent verification failures={len(failures)}")
    return 1 if failures else 0


if __name__ == "__main__":
    sys.exit(main())

