def check_headings(full: str) -> None:
    """Resolve each symbol heading against its own module and its section's.

    A `### ... — agenthicc.foo.bar` subsection re-points the scope only for
    itself; the following `### Symbol` headings belong to the enclosing `##`
    section's module. So a heading passes when the symbol resolves from EITHER
    its own named module or the section's. It is reported as UNSECTIONED when
    neither resolves but the symbol exists somewhere else in the package —
    which is precisely the mis-sectioning defect this goal repaired.
    """
    section: str | None = None
    checked = unsectioned = prose = exempt = 0
    HISTORICAL = re.compile(r"historical|not in the current checkout|superseded", re.I)
    for line in full.splitlines():
        if line.startswith("## "):
            section = line[3:].strip()
            continue
        if not line.startswith("### "):
            continue
        if section is None or HISTORICAL.search(section):
            continue
        raw = line[4:].strip()
        toks = symbol_shape(raw)
        if toks is None:
            prose += 1
            continue
        if HISTORICAL.search(raw):
            exempt += len(toks)
            continue
        own = DOTTED.search(raw)
        candidates: list[str] = []
        if own and "." in own.group(1):
            candidates.append(own.group(1))
        sec = DOTTED.search(section)
        if sec:
            candidates.append(sec.group(1))
        if not candidates:
            exempt += len(toks)
            continue
        for name in toks:
            checked += 1
            if any(_resolves(mod, name) for mod in candidates):
                continue
            elsewhere = [m for m in locate(name) if m not in candidates]
            if elsewhere:
                unsectioned += 1
                fail(
                    f"V3: `### {name}` in '{section}' is filed under "
                    f"{'/'.join(candidates)} but lives in {', '.join(sorted(elsewhere)[:3])}"
                )
            else:
                fail(
                    f"V3: `### {name}` in '{section}' is not resolvable from "
                    f"{'/'.join(candidates)} nor from any module"
                )
    notes.append(
        f"V3: {checked} symbol headings resolved against their module scope, "
        f"{unsectioned} unsectioned, {prose} prose, {exempt} out of scope"
    )


def _resolves(modname: str, name: str) -> bool:
    mod = MODS.get(modname)
    if mod is None:
        return False
    if "." in name:
        cls = getattr(mod, name.split(".")[0], None)
        return cls is not None and hasattr(cls, name.split(".", 1)[1])
    return hasattr(mod, name)

