#!/usr/bin/env python3
"""Verify goal #5: the MkDocs strict build and the navigation completeness.

N1  `mkdocs build --strict` exits 0 and its output contains no WARNING/ERROR
N2  every .md under docs/ appears in the mkdocs.yml nav (no orphans)
N3  every nav target resolves to a file on disk (no dangling entries)
N4  no live page still asserts the two repaired defects (a relative PRD path, or
    the stale cross-file cache anchor)
N5  llms-full.txt is outside docs/, so this build cannot regress goal #4
"""

from __future__ import annotations

import pathlib
import re
import subprocess
import sys

import yaml

ROOT = pathlib.Path("/root/python_projects/agenthicc")
DOCS = ROOT / "docs"

failures: list[str] = []
notes: list[str] = []


def fail(msg: str) -> None:
    failures.append(msg)


def nav_strings(cfg: dict) -> list[str]:
    out: list[str] = []

    def walk(node: object) -> None:
        if isinstance(node, list):
            for item in node:
                walk(item)
        elif isinstance(node, dict):
            for value in node.values():
                walk(value)
        elif isinstance(node, str):
            out.append(node)

    walk(cfg["nav"])
    return out


def check_build() -> None:
    r = subprocess.run(
        ["python", "-m", "mkdocs", "build", "--strict"],
        cwd=ROOT,
        capture_output=True,
        text=True,
        timeout=900,
    )
    out = r.stdout + r.stderr
    warns = len(re.findall(r"^\s*WARNING", out, re.M))
    errs = len(re.findall(r"^\s*ERROR", out, re.M))
    notes.append(f"N1: mkdocs build --strict exit={r.returncode}, WARNING={warns}, ERROR={errs}")
    if r.returncode != 0:
        fail(f"N1: strict build failed:\n{out[-700:]}")
    if warns:
        fail(f"N1: strict build emitted {warns} warning(s)")
    if errs:
        fail(f"N1: strict build emitted {errs} error(s)")
    if "not included in the" in out:
        fail("N1: build still reports pages absent from the nav configuration")


def check_nav() -> None:
    cfg = yaml.safe_load((ROOT / "mkdocs.yml").read_text(encoding="utf-8"))
    nav = nav_strings(cfg)
    disk = sorted(str(p.relative_to(DOCS)) for p in DOCS.rglob("*.md"))
    orphans = [d for d in disk if d not in nav]
    dangling = [n for n in nav if not (DOCS / n).is_file()]
    notes.append(f"N2/N3: nav entries={len(nav)}, pages on disk={len(disk)}")
    for o in orphans:
        fail(f"N2: `{o}` exists under docs/ but is not in the nav")
    for d in dangling:
        fail(f"N3: nav target `{d}` has no file under docs/")
    if not orphans and not dangling:
        notes.append("N2/N3: 0 orphans, 0 dangling nav targets")


def check_no_live_claims() -> None:
    bad = 0
    for page in sorted(DOCS.rglob("*.md")):
        text = page.read_text(encoding="utf-8")
        rel = page.relative_to(DOCS)
        for n, line in enumerate(text.splitlines(), 1):
            if "../../prds/" in line and line.lstrip().startswith("[") and "](" in line:
                bad += 1
                fail(f"N4: {rel}:{n} links out of the docs tree: {line.strip()[:90]}")
            if "../reference/code-plan.md#cache-stable-workflow-turns" in line:
                bad += 1
                fail(f"N4: {rel}:{n} still cites the stale cross-file cache anchor")
    if not bad:
        notes.append("N4: 0 relative PRD links and 0 stale cache anchors in live prose")


def check_llms_untouched() -> None:
    inside = (ROOT / "llms-full.txt").is_relative_to(DOCS)
    notes.append(f"N5: llms-full.txt inside docs/={inside} (expected False)")
    if inside:
        fail("N5: llms-full.txt moved into docs/, so the strict build now validates it")


def main() -> int:
    check_build()
    check_nav()
    check_no_live_claims()
    check_llms_untouched()

    for n in notes:
        print(f"note  {n}")
    for f in failures:
        print(f"FAIL  {f}")
    print(f"\nnav problems={len(failures)}")
    return 1 if failures else 0


if __name__ == "__main__":
    sys.exit(main())

