def resolve_with_table_context(raw: str, offset: int) -> pathlib.Path | None:
    """Resolve a citation, honouring the page's in-table abbreviation rule.

    A table's first row gives the full path (`src/agenthicc/tools/introspect/
    __init__.py:66`); later rows in the same table abbreviate it
    (`introspect/__init__.py:69`). So when a bare/partial path fails to resolve
    on its own, look back inside the enclosing table for a resolved full path
    ending with the same suffix.
    """
    direct = resolve(raw)
    if direct is not None:
        return direct

    before = text[:offset].splitlines()
    # walk back to the start of the enclosing table block
    table_lines: list[str] = []
    for line in reversed(before):
        if not line.lstrip().startswith("|"):
            break
        table_lines.append(line)
    basename = raw.rsplit("/", 1)[-1]
    for line in table_lines:
        for cand in CITE.findall(line):
            other = cand[0]
            if other == raw:
                continue
            full = resolve(other)
            if full is not None and full.name == basename:
                total = len(full.read_text(encoding="utf-8", errors="replace").splitlines())
                if full.name == basename and raw.endswith(other.rsplit("/", 1)[-1]):
                    found = resolve(other)
                    if found is not None:
                        return found
    # last resort: an abbreviation whose suffix matches a unique file on disk
    matches = [
        p
        for p in (ROOT / "src").rglob(basename)
        if not any(s in str(p) for s in ("__pycache__",))
    ]
    return matches[0] if len(matches) == 1 else None

